actions.script:
if (!title) title = ec.l10n.localize('Business alert')
const words = {Firing: ec.l10n.localize('Firing'), Normal: ec.l10n.localize('Normal##alert'), Pending: ec.l10n.localize('Pending'), Recovering: ec.l10n.localize('Recovering'), NoData: ec.l10n.localize('No data (not known)'), Error: ec.l10n.localize('Error (not known)')}
alertLink = link ? String(link) : ''
if (alertLink.startsWith('/') && typeof webHostName !== 'undefined' && webHostName)
    alertLink = 'https://' + String(webHostName).replace(/^https{0,1}:\/\//, '').replace(/\/$/, '') + alertLink
alertLines = Array.from(events || []).slice(0, 50).map(event => {
    const labels = Object.entries(event.labels || {}).filter(([name]) => name !== 'field' && name !== 'rule')
        .map(([name, value]) => name + ' ' + value).join(', ')
    const state = Object.hasOwn(words, String(event.state)) ? words[String(event.state)] : ec.l10n.localize('Not known')
    const reading = event.value == null || event.state === 'NoData' || event.state === 'Error' ? '' : ': ' + Math.round(Number(String(event.value)) * 100) / 100
    return (labels ? labels + ' — ' : '') + state + reading
})

render-mode.text:
${title}
<#list alertLines as line>${line}
</#list>${alertLink}
${ec.l10n.localize('This was sent to you alone, as you may read what its owner reads.')}
